import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { defineConfig, type DefaultTheme } from "vitepress";

const root = resolve(import.meta.dirname, "../..");
const { version } = JSON.parse(readFileSync(resolve(root, "package.json"), "utf8"));

// Generated by "npm run docs:api"
const apiSidebarFile = resolve(import.meta.dirname, "../api/typedoc-sidebar.json");
const apiSidebar: Array<DefaultTheme.SidebarItem> = existsSync(apiSidebarFile) ?
    JSON.parse(readFileSync(apiSidebarFile, "utf8")) :
    [];

const modules = (items: Record<string, string>): Array<DefaultTheme.SidebarItem> => Object.entries(items)
    .map(([text, file]) => ({
        text,
        link: `/modules/${file}`,
    }));

